def getPerfectPairsCount(arr):
    # 令 a = min(|x|,|y|), b = max(|x|,|y|)：条件化简为 b <= 2a 且 a > 0
    a = sorted(abs(x) for x in arr if x != 0)
    n, ans, j = len(a), 0, 0
    for i in range(n):
        j = max(j, i + 1)
        while j < n and a[j] <= 2 * a[i]:
            j += 1
        ans += j - i - 1
    return ans
